<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/session.php'; require_once __DIR__ . '/db.php';
function e(mixed $value): string { return htmlspecialchars((string) ($value ?? ''), ENT_QUOTES, 'UTF-8'); }
$id = filter_var($_GET['id'] ?? null, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]); $token = preg_replace('/[^a-f0-9]/i', '', (string) ($_GET['token'] ?? '')); $receipt = false;
if ($id && strlen($token) === 64) { try { $pdo=getDatabaseConnection(); $q=$pdo->prepare("SELECT inv.*, i.reference_no, i.event_type, i.target_event_date FROM invoices inv JOIN inquiries i ON i.id=inv.inquiry_id WHERE inv.id=? AND inv.public_token=? AND LOWER(inv.status) IN ('paid','down payment paid','50% paid')"); $q->execute([$id,$token]); $receipt=$q->fetch(); } catch(PDOException $exception){ error_log('LEGATO receipt: '.$exception->getMessage()); } }
if(!$receipt) http_response_code(404);
?><!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Payment Receipt | LEGATO</title><script src="https://cdn.tailwindcss.com"></script><script>tailwind.config={theme:{extend:{colors:{gold:'#D4AF37',ivory:'#F5F2EB'}}}}</script><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Montserrat:wght@400;600;700&family=Playfair+Display:wght@600;700&display=swap" rel="stylesheet"></head><body class="min-h-screen bg-[#121212] font-[Montserrat] text-[#F5F2EB]"><main class="mx-auto flex min-h-screen max-w-3xl items-center p-5"><section class="w-full rounded-2xl border border-[#10B981]/40 bg-[#181818] shadow-2xl"><?php if(!$receipt): ?><div class="p-10 text-center"><p class="text-sm text-[#9CA3AF]">Receipt unavailable.</p></div><?php else: ?><header class="border-b border-[#282828] bg-[#121212] p-8"><img src="Assest/legato1.png" class="h-14 w-auto" alt="LEGATO"><span class="mt-6 inline-block rounded bg-[#10B981]/10 px-3 py-1 font-mono text-[10px] uppercase tracking-wider text-[#10B981]">50% Payment Confirmed</span><h1 class="mt-3 font-[Playfair_Display] text-4xl">Official Payment Receipt</h1></header><div class="p-8"><div class="grid gap-5 text-sm sm:grid-cols-2"><p><span class="text-[#9CA3AF]">Receipt number</span><br><strong class="font-mono text-[#D4AF37]"><?php echo e($receipt['invoice_number']); ?></strong></p><p><span class="text-[#9CA3AF]">Payment date</span><br><?php echo e($receipt['payment_date'] ?? $receipt['created_at']); ?></p><p><span class="text-[#9CA3AF]">Customer</span><br><?php echo e($receipt['client_name']); ?></p><p><span class="text-[#9CA3AF]">Event</span><br><?php echo e($receipt['event_type']); ?> · <?php echo e($receipt['target_event_date']); ?></p></div><div class="mt-7 space-y-3 border-y border-[#282828] py-6 text-sm"><div class="flex justify-between"><span class="text-[#9CA3AF]">Total package price</span><strong>&#8369;<?php echo number_format((float)$receipt['total_amount'],2); ?></strong></div><div class="flex justify-between"><span class="text-[#10B981]">Amount paid (50%)</span><strong class="font-mono text-xl text-[#10B981]">&#8369;<?php echo number_format((float)$receipt['amount_paid'],2); ?></strong></div><div class="flex justify-between"><span class="text-[#9CA3AF]">Remaining balance</span><strong>&#8369;<?php echo number_format((float)$receipt['remaining_balance'],2); ?></strong></div></div><button onclick="window.print()" class="mt-7 w-full rounded bg-[#D4AF37] px-4 py-3 text-xs font-bold uppercase tracking-wider text-[#121212]">Print / Download Official Receipt</button></div><?php endif; ?></section></main></body></html>
